// The web's screen rules as data (resources/web/content.json, generated by scripts/gen_i18n.mjs from
// curriculum.ts, campaign.ts, campaignReport.ts, debrief.ts, shortcuts.ts and the content JSON files):
// curriculum stages, campaign constants, default shortcuts, the Academy lessons (charts, widgets,
// questions), the glossary's structure and the guided first trade's steps. Never retyped, so a web
// change reaches the desktop through the generator (check_i18n.mjs fails on drift).
#pragma once

#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <variant>
#include <vector>

namespace tradelab::desktop {

struct Stage {
  std::string id;
  std::vector<std::string> requires_;  // direct prerequisites
  std::vector<std::string> missions;   // assessment missions
  std::vector<std::string> lessons;    // Academy lessons (stages without a mission)
  std::vector<std::string> unlocks;    // "short", "leverage", "optionsBuy", "optionsWrite"
};

struct LessonCandle {
  double o = 0, h = 0, l = 0, c = 0, v = 0;
};

// A labeled horizontal line of a lesson chart: entry, stop, target, liquidation, mark, last or strike.
struct LessonLevel {
  std::string kind;
  double price = 0;
};

struct LessonChart {
  std::string market;
  std::string interval;
  std::vector<LessonCandle> candles;
  int highlight = 0;  // 1-based bar to highlight, 0 = none
  int known = 0;      // bars already closed (0 = all); the rest is the unknown future
  bool anatomy = false;
  std::vector<LessonLevel> levels;
};

// Ticket sandbox (academy.ts TicketWidget): a perpetual ticket that sends nothing; `edit` lists the
// fields the player may change (side, qty, leverage, stop, target).
struct TicketWidget {
  std::string market;
  double equity = 0;
  double entry = 0;
  bool buy = true;
  double qty = 0;
  int leverage = 1;
  int max_leverage = 1;
  std::optional<double> stop;
  std::optional<double> target;
  double mmr = 0;
  double lot = 1;
  std::vector<std::string> edit;
  [[nodiscard]] bool editable(std::string_view field) const;
};

struct TableColumn {
  std::string id;
  std::optional<int> digits;
  std::string suffix;
};

// A number (written in the locale) or the id of a text cell of the step.
struct TableCell {
  bool number = true;
  double value = 0;
  std::string id;
};

struct TableWidget {
  std::string market;
  std::vector<TableColumn> columns;
  std::vector<std::vector<TableCell>> rows;
};

struct PayoffLeg {
  std::string kind;  // call, put, perp
  bool buy = true;
  double qty = 0;
  double strike = 0;  // options only
  double price = 0;   // premium per unit, or the perpetual's entry
};

struct PayoffWidget {
  std::string market;
  std::vector<PayoffLeg> legs;
  double lo = 0;
  double hi = 0;
  bool hide_analytics = false;  // a question asks for the breakevens or the maximum profit and loss
};

using LessonWidget = std::variant<std::monostate, TicketWidget, TableWidget, PayoffWidget>;

struct LessonChoice {
  enum class Kind : std::uint8_t { Bar, Pct, Text };
  Kind kind = Kind::Bar;
  int bar = 0;
  double value = 0;  // percent (1.21 = +1,21%)
  std::string id;    // text choice id
};

// academy.ts Question: a choice, a typed number (either decimal mark) or a value of the step's ticket
// sandbox brought within a tolerance of a target (set).
struct StepQuestion {
  enum class Type : std::uint8_t { Choice, Number, Set };
  Type type = Type::Choice;
  std::vector<LessonChoice> choices;  // Choice
  int answer = -1;                    // Choice: the right choice
  double value = 0;                   // Number: the answer; Set: the target
  double tolerance = 0;               // Number, Set
  std::string unit;                   // Number: shown after the input
  std::string field;                  // Set: a sandbox input or output
};

struct LessonStep {
  std::string id;
  std::string phase;  // concept, demo, decision, transfer
  std::optional<LessonChart> chart;
  LessonWidget widget;
  std::optional<StepQuestion> question;
  std::vector<std::string> terms;  // glossary terms its texts link ([[id|text]])
  [[nodiscard]] bool is_question() const { return question.has_value(); }
};

struct AcademyLesson {
  std::string id;
  std::string stage;
  std::vector<LessonStep> steps;
};

// glossary.json structure (texts: the glossary.<id>.* catalog rows).
struct GlossaryEntry {
  std::string id;
  std::string stage;
  std::vector<std::string> related;
};

// coach.json: a step of the guided first trade, its target and what completes it (next, stop, advance).
struct CoachStepDef {
  std::string id;
  std::string target;     // chart, ticket, stop, risk, advance, debrief
  std::string completes;  // next, stop, advance
};

struct WebContent {
  std::vector<Stage> stages;
  int locked_leverage_cap = 2;
  std::string campaign_capital;
  std::string campaign_min_capital;
  int campaign_history = 20;
  int report_min_trades = 30;
  int after_release_bars = 10;
  std::vector<std::string> shortcut_actions;
  std::vector<std::pair<std::string, std::string>> default_keymap;  // action -> key, in action order
  std::vector<AcademyLesson> lessons;
  std::vector<GlossaryEntry> glossary;
  std::vector<CoachStepDef> coach;
  std::map<std::string, std::string, std::less<>> finding_terms;  // debrief finding code -> glossary term

  [[nodiscard]] const Stage* stage(std::string_view id) const;
  [[nodiscard]] const AcademyLesson* lesson(std::string_view id) const;
  [[nodiscard]] const GlossaryEntry* term(std::string_view id) const;
};

// Parses content.json; std::nullopt when it is not a valid document.
std::optional<WebContent> parse_web_content(std::string_view json);
// The content built into the binary, parsed once.
const WebContent& web_content();

}  // namespace tradelab::desktop
